INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('06513f5c-8933-51dc-a9ae-5977c079276d', 'Lithuania Order No V3-16 on the work of auditors', 'Order No V3-16 on the work of auditors and audit firms', 'Order No V3-16 on the work of auditors and audit firms', 'Order No V3-16 on the work of auditors and audit firms', 'Order No V3-16 on the work of auditors and audit firms', 'Lithuania', 'governance', 'in_force', '2024-01-01'::date, 'Lithuania', 'https://www.carrotsandsticks.org/policies/104_14', ARRAY['lithuania', 'mandatory', 'mandatory_regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('73fbf75a-6d98-5609-a12f-209425235254', 'Lithuania Order No V3-15 on the work and internal', 'Order No V3-15 on the work and internal organisation of audit firms and independent sustainability reporting service providers', 'Order No V3-15 establishes requirements for the internal organization and work of audit firms and independent sustainability reporting service providers in Lithuania. It mandates that these entities develop and implement internal policies and procedures to ensure compliance with sustainability reporting standards. The order applies to all audit firms and independent providers engaged in sustainability assurance services. Compliance with these requirements is mandatory as part of the Lithuanian financial reporting and assurance services law.', 'Order No V3-15 establishes requirements for the internal organization and work of audit firms and independent sustainability reporting service providers in Lithuania. It mandates that these entities develop and implement internal policies and procedures to ensure compliance with sustainability reporting standards. The order applies to all audit firms and independent providers engaged in sustainability assurance services. Compliance with these requirements is mandatory as part of the Lithuanian financial reporting and assurance services law.', 'Order No V3-15 establishes requirements for the internal organization and work of audit firms and independent sustainability reporting service providers in Lithuania. It mandates that these entities develop and implement internal policies and procedures to ensure compliance with sustainability reporting standards. The order applies to all audit firms and independent providers engaged in sustainability assurance services. Compliance with these requirements is mandatory as part of the Lithuanian financial reporting and assurance services law.', 'Lithuania', 'climate', 'in_force', '2024-01-01'::date, 'Lithuania', 'https://www.carrotsandsticks.org/policies/104_15', ARRAY['sdg13', 'mandatory', 'sdg16', 'mandatory_regulations', 'sdg12', 'disclosure', 'lithuania']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('930dbffa-dc94-5962-94bd-08c5bb00bc5c', 'Lithuania Order No VII- 1864 Law on the Approval', 'Order No VII- 1864 Law on the Approval, Entry into Force and Implementation of the Civil Code of the Republic of Lithuania.', 'The Order No VII-1864 establishes the Civil Code of the Republic of Lithuania, which governs civil legal relationships. It applies to all civil legal relations arising after its entry into force on July 1, 2001, with certain exceptions. The Code also addresses the application of previous laws and regulations until its enactment, ensuring continuity in legal proceedings. It emphasizes principles of fairness, justice, and reasonableness in judicial disputes. The provisions are mandatory for all entities involved in civil legal matters in Lithuania.', 'The Order No VII-1864 establishes the Civil Code of the Republic of Lithuania, which governs civil legal relationships. It applies to all civil legal relations arising after its entry into force on July 1, 2001, with certain exceptions. The Code also addresses the application of previous laws and regulations until its enactment, ensuring continuity in legal proceedings. It emphasizes principles of fairness, justice, and reasonableness in judicial disputes. The provisions are mandatory for all entities involved in civil legal matters in Lithuania.', 'The Order No VII-1864 establishes the Civil Code of the Republic of Lithuania, which governs civil legal relationships. It applies to all civil legal relations arising after its entry into force on July 1, 2001, with certain exceptions. The Code also addresses the application of previous laws and regulations until its enactment, ensuring continuity in legal proceedings. It emphasizes principles of fairness, justice, and reasonableness in judicial disputes. The provisions are mandatory for all entities involved in civil legal matters in Lithuania.', 'Lithuania', 'governance', 'in_force', '2024-01-01'::date, 'Lithuania', 'https://www.carrotsandsticks.org/policies/104_16', ARRAY['other sustainability policy', 'regulations', 'mandatory', 'sdg16', 'lithuania']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('65c5371a-b1f9-59de-b8cf-37a8c5b90ec7', 'Lithuania XIV-2811 Reporting of companies and groups of companies', 'XIV-2811 Reporting of companies and groups of companies law', 'This policy was published in 2024 by Lithuania. It addresses sustainability and corporate responsibility requirements.', 'This policy was published in 2024 by Lithuania. It addresses sustainability and corporate responsibility requirements.', 'This policy was published in 2024 by Lithuania. It addresses sustainability and corporate responsibility requirements.', 'Lithuania', 'climate', 'in_force', '2024-01-01'::date, 'Lithuania', 'https://www.carrotsandsticks.org/policies/104_7', ARRAY['sdg13', 'regulations', 'mandatory', 'sdg16', 'sdg12', 'lithuania']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('54d08ae9-1105-518b-9f62-722d18552272', 'Lithuania VIII-1227 Law on Audit of Financial Statements', 'VIII-1227 Law of the Republic of Lithuania on Audit of Financial Statements and Other Assurance Services', 'The "VIII-1227 Law of the Republic of Lithuania on Audit of Financial Statements and Other Assurance Services" aims to enhance public trust in financial reports and sustainability disclosures. It sets requirements for financial statement audits, assurance services, and regulates auditors, audit firms, and sustainability assurance providers. Targeted at ensuring quality and credibility.', 'The "VIII-1227 Law of the Republic of Lithuania on Audit of Financial Statements and Other Assurance Services" aims to enhance public trust in financial reports and sustainability disclosures. It sets requirements for financial statement audits, assurance services, and regulates auditors, audit firms, and sustainability assurance providers. Targeted at ensuring quality and credibility.', 'The "VIII-1227 Law of the Republic of Lithuania on Audit of Financial Statements and Other Assurance Services" aims to enhance public trust in financial reports and sustainability disclosures. It sets requirements for financial statement audits, assurance services, and regulates auditors, audit firms, and sustainability assurance providers. Targeted at ensuring quality and credibility.', 'Lithuania', 'climate', 'in_force', '2024-01-01'::date, 'Lithuania', 'https://www.carrotsandsticks.org/policies/104_8', ARRAY['sdg13', 'regulations', 'mandatory', 'sdg16', 'sdg12', 'lithuania']::text[]) ON CONFLICT (id) DO NOTHING;
