INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('9e00262c-0367-5ed2-99c5-039f49f0d915', 'Lithuania Labour Code', 'Labour Code of The Republic of Lithuania', 'The Labour Code of the Republic of Lithuania, effective since 2017, governs labor relations, overrides previous laws, and outlines implementation guidelines. It targets employers, employees, and government bodies involved in labor-related matters in Lithuania.', 'The Labour Code of the Republic of Lithuania, effective since 2017, governs labor relations, overrides previous laws, and outlines implementation guidelines. It targets employers, employees, and government bodies involved in labor-related matters in Lithuania.', 'The Labour Code of the Republic of Lithuania, effective since 2017, governs labor relations, overrides previous laws, and outlines implementation guidelines. It targets employers, employees, and government bodies involved in labor-related matters in Lithuania.', 'Lithuania', 'social', 'in_force', '2023-01-01'::date, 'Lithuania', 'https://www.carrotsandsticks.org/policies/104_5', ARRAY['lithuania', 'sdg8', 'mandatory', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('892c9067-cde4-58f4-b225-a0e7ea3b1d37', 'Lithuania Corporate Governance Code for the Companies Listed', 'Corporate Governance Code for the Companies Listed on the NASDAQ Vilnius', 'The key objectives of this Corporate Governance Code for the Companies Listed on Nasdaq Vilnius (hereinafter referred to as the “Code”) include recommending the companies what basic principles they should follow in order to ensure the uniform understanding of the transparency of their management and business operations not only by domestic but also by foreign investors; encouraging the companies to improve their governance framework and disclosure of information on their business operations; encouraging the companies to ensure the quality of governance as means to improve the company''s performance; enhancing confidence of domestic and foreign investors and other stakeholders in the companies and their governance framework; disseminating information on the activities of Nasdaq Vilnius on the international level and boost the confidence of domestic and foreign investors in the Lithuanian securities market.', 'The key objectives of this Corporate Governance Code for the Companies Listed on Nasdaq Vilnius (hereinafter referred to as the “Code”) include recommending the companies what basic principles they should follow in order to ensure the uniform understanding of the transparency of their management and business operations not only by domestic but also by foreign investors; encouraging the companies to improve their governance framework and disclosure of information on their business operations; encouraging the companies to ensure the quality of governance as means to improve the company''s performance; enhancing confidence of domestic and foreign investors and other stakeholders in the companies and their governance framework; disseminating information on the activities of Nasdaq Vilnius on the international level and boost the confidence of domestic and foreign investors in the Lithuanian securities market.', 'The key objectives of this Corporate Governance Code for the Companies Listed on Nasdaq Vilnius (hereinafter referred to as the “Code”) include recommending the companies what basic principles they should follow in order to ensure the uniform understanding of the transparency of their management and business operations not only by domestic but also by foreign investors; encouraging the companies to improve their governance framework and disclosure of information on their business operations; encouraging the companies to ensure the quality of governance as means to improve the company''s performance; enhancing confidence of domestic and foreign investors and other stakeholders in the companies and their governance framework; disseminating information on the activities of Nasdaq Vilnius on the international level and boost the confidence of domestic and foreign investors in the Lithuanian securities market.', 'Lithuania', 'governance', 'in_force', '2019-01-01'::date, 'Lithuania', 'https://www.carrotsandsticks.org/policies/104_4', ARRAY['other sustainability policy', 'regulations', 'mandatory', 'sdg16', 'lithuania']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ca1033b2-c972-56ab-aacd-7558a6348432', 'Lithuania''s Action Plan on the Implementation of the', 'Lithuania''s Action Plan on the Implementation of the United Nations Guiding Principles on Business and Human Rights', 'This document contains former, current and future actions and measures by the Government of the Republic of Lithuaniaas regards the implementation of the UN Principles on Business and Human Rights, as well as the information as regards the provisions of national legislation pertinent to this field. Additionally, the document specifies actions, planned or implemented measures and legislative provisions intended to consolidate Lithuania''s duty to protect, defend and respect human rights and encourage businesses to ensure respect and responsibility in the field of human rights, as well as to ensure effective remedies.', 'This document contains former, current and future actions and measures by the Government of the Republic of Lithuaniaas regards the implementation of the UN Principles on Business and Human Rights, as well as the information as regards the provisions of national legislation pertinent to this field. Additionally, the document specifies actions, planned or implemented measures and legislative provisions intended to consolidate Lithuania''s duty to protect, defend and respect human rights and encourage businesses to ensure respect and responsibility in the field of human rights, as well as to ensure effective remedies.', 'This document contains former, current and future actions and measures by the Government of the Republic of Lithuaniaas regards the implementation of the UN Principles on Business and Human Rights, as well as the information as regards the provisions of national legislation pertinent to this field. Additionally, the document specifies actions, planned or implemented measures and legislative provisions intended to consolidate Lithuania''s duty to protect, defend and respect human rights and encourage businesses to ensure respect and responsibility in the field of human rights, as well as to ensure effective remedies.', 'Lithuania', 'social', 'in_force', '2015-01-01'::date, 'Lithuania', 'https://www.carrotsandsticks.org/policies/104_2', ARRAY['sdg4', 'other sustainability policy', 'sdg10', 'regulations', 'sdg16', 'lithuania', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('8ba7418e-125c-588e-bbdc-4758bba6871d', 'Lithuania Corporate Governance Code for the Companies Listed', 'The Corporate Governance Code for the Companies Listed on NASDAQ OMX Vilnius, 2009', 'The principle objectives of the Code are the following: recommend the listed companies what basic principles they should follow in order to ensure equal understanding of transparent management and operation not only by domestic but also by foreign investors, encourage the listed companies to improve their governance framework and disclosure of information on their activities, encourage the listed companies to enhance management quality as means to improve the company’s performance, promote the activities of the listed companies on the international level and enhance confidence of domestic and foreign investors as well as other stakeholders in the companies and their governance framework, promote activities of NASDAQ OMX Vilnius on the international level, to bolster confidence of domestic and foreign investors in the Lithuanian capital market.', 'The principle objectives of the Code are the following: recommend the listed companies what basic principles they should follow in order to ensure equal understanding of transparent management and operation not only by domestic but also by foreign investors, encourage the listed companies to improve their governance framework and disclosure of information on their activities, encourage the listed companies to enhance management quality as means to improve the company’s performance, promote the activities of the listed companies on the international level and enhance confidence of domestic and foreign investors as well as other stakeholders in the companies and their governance framework, promote activities of NASDAQ OMX Vilnius on the international level, to bolster confidence of domestic and foreign investors in the Lithuanian capital market.', 'The principle objectives of the Code are the following: recommend the listed companies what basic principles they should follow in order to ensure equal understanding of transparent management and operation not only by domestic but also by foreign investors, encourage the listed companies to improve their governance framework and disclosure of information on their activities, encourage the listed companies to enhance management quality as means to improve the company’s performance, promote the activities of the listed companies on the international level and enhance confidence of domestic and foreign investors as well as other stakeholders in the companies and their governance framework, promote activities of NASDAQ OMX Vilnius on the international level, to bolster confidence of domestic and foreign investors in the Lithuanian capital market.', 'Lithuania', 'governance', 'in_force', '2009-01-01'::date, 'Lithuania', 'https://www.carrotsandsticks.org/policies/104_1', ARRAY['other sustainability policy', 'regulations', 'mandatory', 'sdg16', 'lithuania']::text[]) ON CONFLICT (id) DO NOTHING;
