INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('4b78f044-4691-57c4-9eb3-a168fb3e749d', 'Luxembourg Chamber of Deputies Bill', 'Chamber of Deputies Bill No. 8370', 'Luxembourg''s Chamber of Deputies Bill No. 8370 transposes EU directives on sustainability reporting and adjusts size criteria for businesses. It modifies various commercial and financial laws. The policy aims to enhance transparency and compliance for companies, particularly affecting financial and audit sectors.', 'Luxembourg''s Chamber of Deputies Bill No. 8370 transposes EU directives on sustainability reporting and adjusts size criteria for businesses. It modifies various commercial and financial laws. The policy aims to enhance transparency and compliance for companies, particularly affecting financial and audit sectors.', 'Luxembourg''s Chamber of Deputies Bill No. 8370 transposes EU directives on sustainability reporting and adjusts size criteria for businesses. It modifies various commercial and financial laws. The policy aims to enhance transparency and compliance for companies, particularly affecting financial and audit sectors.', 'Luxembourg', 'climate', 'in_force', '2024-01-01'::date, 'Luxembourg', 'https://www.carrotsandsticks.org/policies/105_15', ARRAY['sdg16', 'mandatory', 'luxembourg', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('0aed03be-2164-5426-af61-7dfea4e19a55', 'Luxembourg Circular CSSF 24/863 Guidelines on funds’ names using', 'Circular CSSF 24/863 Guidelines on funds’ names using ESG or sustainability-related terms', 'The Circular CSSF 24/863 from Luxembourg outlines guidelines for funds using ESG or sustainability terms, ensuring clarity and fairness in fund names. Applicable to UCITS and AIF managers, it aligns with ESMA guidelines to prevent misleading practices, effective from November 21, 2024.', 'The Circular CSSF 24/863 from Luxembourg outlines guidelines for funds using ESG or sustainability terms, ensuring clarity and fairness in fund names. Applicable to UCITS and AIF managers, it aligns with ESMA guidelines to prevent misleading practices, effective from November 21, 2024.', 'The Circular CSSF 24/863 from Luxembourg outlines guidelines for funds using ESG or sustainability terms, ensuring clarity and fairness in fund names. Applicable to UCITS and AIF managers, it aligns with ESMA guidelines to prevent misleading practices, effective from November 21, 2024.', 'Luxembourg', 'climate', 'in_force', '2024-01-01'::date, 'Luxembourg', 'https://www.carrotsandsticks.org/policies/105_17', ARRAY['guidance_frameworks', 'sdg13', 'sdg16', 'sdg12', 'luxembourg', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('faf106c0-40bd-51bf-a2d7-dcd886acc67c', 'Principles of Corporate Governance of the Luxembourg Stock Exchange', 'Principles of Corporate Governance of the Luxembourg Stock Exchange', 'The "Principles of Corporate Governance of the Luxembourg Stock Exchange" outline governance practices for companies listed on the Luxembourg Stock Exchange, focusing on transparency, sustainability, board responsibilities, and shareholder rights. It targets companies, board members, and investors, aiming to promote long-term value creation and economic growth through good governance.', 'The "Principles of Corporate Governance of the Luxembourg Stock Exchange" outline governance practices for companies listed on the Luxembourg Stock Exchange, focusing on transparency, sustainability, board responsibilities, and shareholder rights. It targets companies, board members, and investors, aiming to promote long-term value creation and economic growth through good governance.', 'The "Principles of Corporate Governance of the Luxembourg Stock Exchange" outline governance practices for companies listed on the Luxembourg Stock Exchange, focusing on transparency, sustainability, board responsibilities, and shareholder rights. It targets companies, board members, and investors, aiming to promote long-term value creation and economic growth through good governance.', 'Luxembourg', 'governance', 'in_force', '2024-01-01'::date, 'Luxembourg', 'https://www.carrotsandsticks.org/policies/105_19', ARRAY['sdg16', 'guidance_frameworks', 'luxembourg', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('10505f09-9ccf-54f4-822a-5c7eba68fee7', 'Luxembourg Guide to ESG Reporting', 'Guide to ESG Reporting, 2021', 'This guide reaffirms Stock Exchange''s commitment to contributing to the achievement of the SDGs by furthering transparency and supporting Principle 2 of the "World Federation of Exchanges (WFE) Sustainability Principles", which refers to the role of stock exchanges in enhancing the availability of investor-relevant, decision-useful ESG information.', 'This guide reaffirms Stock Exchange''s commitment to contributing to the achievement of the SDGs by furthering transparency and supporting Principle 2 of the "World Federation of Exchanges (WFE) Sustainability Principles", which refers to the role of stock exchanges in enhancing the availability of investor-relevant, decision-useful ESG information.', 'This guide reaffirms Stock Exchange''s commitment to contributing to the achievement of the SDGs by furthering transparency and supporting Principle 2 of the "World Federation of Exchanges (WFE) Sustainability Principles", which refers to the role of stock exchanges in enhancing the availability of investor-relevant, decision-useful ESG information.', 'Luxembourg', 'climate', 'in_force', '2021-01-01'::date, 'Luxembourg', 'https://www.carrotsandsticks.org/policies/105_7', ARRAY['other sustainability policy', 'mandatory', 'sdg16', 'mandatory_regulations', 'luxembourg']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('254ba1ee-ae89-5be8-9f7c-1f2cb912aefd', 'Luxembourg Guide to ESG Reporting', 'Guide to ESG Reporting, 2019', 'With the growing global concern surrounding the achievement of the Sustainable Development Goals (SDG) by 2030, investors and other financial marketplayers are increasingly interested in understanding how organisations manage their material ESG opportunities and risks, and how they deliver on ESG positive impact. Stock exchanges have the ability to act as catalysts for financial markets in providing guidance for appropriate ESG reporting.LuxSE are committed to promoting transparency on ESG matters through encouraging the reporting thereof. This document therefore provides information on how organisations can integrate such ESG matters into their reporting by focusing on providing guidance for three different kinds of stakeholders: 1 Companies, 2 Issuers of debt instruments (i.e. bonds), and 3 Asset Managers active in SRI funds.', 'With the growing global concern surrounding the achievement of the Sustainable Development Goals (SDG) by 2030, investors and other financial marketplayers are increasingly interested in understanding how organisations manage their material ESG opportunities and risks, and how they deliver on ESG positive impact. Stock exchanges have the ability to act as catalysts for financial markets in providing guidance for appropriate ESG reporting.LuxSE are committed to promoting transparency on ESG matters through encouraging the reporting thereof. This document therefore provides information on how organisations can integrate such ESG matters into their reporting by focusing on providing guidance for three different kinds of stakeholders: 1 Companies, 2 Issuers of debt instruments (i.e. bonds), and 3 Asset Managers active in SRI funds.', 'With the growing global concern surrounding the achievement of the Sustainable Development Goals (SDG) by 2030, investors and other financial marketplayers are increasingly interested in understanding how organisations manage their material ESG opportunities and risks, and how they deliver on ESG positive impact. Stock exchanges have the ability to act as catalysts for financial markets in providing guidance for appropriate ESG reporting.LuxSE are committed to promoting transparency on ESG matters through encouraging the reporting thereof. This document therefore provides information on how organisations can integrate such ESG matters into their reporting by focusing on providing guidance for three different kinds of stakeholders: 1 Companies, 2 Issuers of debt instruments (i.e. bonds), and 3 Asset Managers active in SRI funds.', 'Luxembourg', 'climate', 'in_force', '2019-01-01'::date, 'Luxembourg', 'https://www.carrotsandsticks.org/policies/105_2', ARRAY['other sustainability policy', 'mandatory', 'sdg16', 'mandatory_regulations', 'luxembourg']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('95d88632-cdb8-5ead-8d00-61f3d10c237d', 'Luxembourg Coalition Agreement', 'Coalition Agreement 2018-2023', 'The Accord de Coalition 2018-2023 is a political agreement signed by the three parties forming the Luxembourg government in 2018. The coalition agreement outlines the parties'' plans for the next five years regarding various issues, such as education, healthcare, and the economy. The agreement also includes specific measures related to the environment and sustainability, such as the promotion of renewable energies and the fight against climate change. The accord emphasizes the importance of social cohesion, human rights, and diversity, and aims to strengthen Luxembourg''s position as a European and international hub for finance, research, and innovation.', 'The Accord de Coalition 2018-2023 is a political agreement signed by the three parties forming the Luxembourg government in 2018. The coalition agreement outlines the parties'' plans for the next five years regarding various issues, such as education, healthcare, and the economy. The agreement also includes specific measures related to the environment and sustainability, such as the promotion of renewable energies and the fight against climate change. The accord emphasizes the importance of social cohesion, human rights, and diversity, and aims to strengthen Luxembourg''s position as a European and international hub for finance, research, and innovation.', 'The Accord de Coalition 2018-2023 is a political agreement signed by the three parties forming the Luxembourg government in 2018. The coalition agreement outlines the parties'' plans for the next five years regarding various issues, such as education, healthcare, and the economy. The agreement also includes specific measures related to the environment and sustainability, such as the promotion of renewable energies and the fight against climate change. The accord emphasizes the importance of social cohesion, human rights, and diversity, and aims to strengthen Luxembourg''s position as a European and international hub for finance, research, and innovation.', 'Luxembourg', 'climate', 'in_force', '2018-01-01'::date, 'Luxembourg', 'https://www.carrotsandsticks.org/policies/105_14', ARRAY['sdg8', 'sdg13', 'sdg2', 'sdg7', 'mandatory', 'sdg16', 'mandatory_regulations', 'disclosure', 'luxembourg', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('83b55452-22f2-5173-b0d8-79b158604e4e', 'National Action Plan of Luxembourg for the implementation', 'National Action Plan of Luxembourg for the implementation of the United Nations Guiding Principles on Business and Human Rights 2018-2019', 'This document describes the international and national context which saw the adoption of the first edition of Luxembourg‘s National Action Plan (NAP) for the implementation of the UN Guiding Principles. It is prepared by the Government, under the coordination of the Ministry of Foreign and European Affairs, within the framework of the Inter-ministerial Committee on Human Rights and on the basis of an in-depth dialogue with private sector non-governmental actors and civil society.', 'This document describes the international and national context which saw the adoption of the first edition of Luxembourg‘s National Action Plan (NAP) for the implementation of the UN Guiding Principles. It is prepared by the Government, under the coordination of the Ministry of Foreign and European Affairs, within the framework of the Inter-ministerial Committee on Human Rights and on the basis of an in-depth dialogue with private sector non-governmental actors and civil society.', 'This document describes the international and national context which saw the adoption of the first edition of Luxembourg‘s National Action Plan (NAP) for the implementation of the UN Guiding Principles. It is prepared by the Government, under the coordination of the Ministry of Foreign and European Affairs, within the framework of the Inter-ministerial Committee on Human Rights and on the basis of an in-depth dialogue with private sector non-governmental actors and civil society.', 'Luxembourg', 'climate', 'in_force', '2018-01-01'::date, 'Luxembourg', 'https://www.carrotsandsticks.org/policies/105_8', ARRAY['sdg13', 'regulations', 'sdg16', 'disclosure', 'luxembourg', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('08271a84-fef6-5604-9a86-f477dcd7c78f', 'X Principles of Corporate Governance of the Luxembourg', 'The X Principles of Corporate Governance of the Luxembourg Stock Exchange (4th edition-revised version), 2017', 'The X Principles have been drawn up for limited companies with a single-tier governance structure (with a board of directors), which is the form most commonly adopted by companies in Luxembourg. However, they are also intended to apply to other forms of companies, including those with a two-tier governance structure, including a supervisory board and an executive board. In this case, the X Principles must be interpreted and applied mutatis mutandis. The X Principles include three series of rules: the actual mandatory (“compliance”) Principles; the “comply or explain” Recommendations (that is to say, those which are mandatory save in exceptional justified circumstances); and the Guidelines, which are indicative but not binding.', 'The X Principles have been drawn up for limited companies with a single-tier governance structure (with a board of directors), which is the form most commonly adopted by companies in Luxembourg. However, they are also intended to apply to other forms of companies, including those with a two-tier governance structure, including a supervisory board and an executive board. In this case, the X Principles must be interpreted and applied mutatis mutandis. The X Principles include three series of rules: the actual mandatory (“compliance”) Principles; the “comply or explain” Recommendations (that is to say, those which are mandatory save in exceptional justified circumstances); and the Guidelines, which are indicative but not binding.', 'The X Principles have been drawn up for limited companies with a single-tier governance structure (with a board of directors), which is the form most commonly adopted by companies in Luxembourg. However, they are also intended to apply to other forms of companies, including those with a two-tier governance structure, including a supervisory board and an executive board. In this case, the X Principles must be interpreted and applied mutatis mutandis. The X Principles include three series of rules: the actual mandatory (“compliance”) Principles; the “comply or explain” Recommendations (that is to say, those which are mandatory save in exceptional justified circumstances); and the Guidelines, which are indicative but not binding.', 'Luxembourg', 'governance', 'in_force', '2017-01-01'::date, 'Luxembourg', 'https://www.carrotsandsticks.org/policies/105_1', ARRAY['guidance_frameworks', 'sdg16', 'disclosure', 'luxembourg', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('401502ac-685b-5f9a-8909-a59bedc6cdaa', 'Luxembourg Compendium of Legislation A –– N° 156', 'Compendium of Legislation A –– N° 156', 'This document outlines the law of 23 July 2016 concerning the publication of non-financial information and information relating to diversity by certain large companies and certain groups and amending various provisions relating to the accounting and annual accounts of companies as well as consolidated accounts of certain forms of companies.', 'This document outlines the law of 23 July 2016 concerning the publication of non-financial information and information relating to diversity by certain large companies and certain groups and amending various provisions relating to the accounting and annual accounts of companies as well as consolidated accounts of certain forms of companies.', 'This document outlines the law of 23 July 2016 concerning the publication of non-financial information and information relating to diversity by certain large companies and certain groups and amending various provisions relating to the accounting and annual accounts of companies as well as consolidated accounts of certain forms of companies.', 'Luxembourg', 'governance', 'in_force', '2016-01-01'::date, 'Luxembourg', 'https://www.carrotsandsticks.org/policies/105_10', ARRAY['mandatory', 'luxembourg', 'other sustainability policy', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e00dee21-429a-53bd-9644-74c9c3761465', 'Luxembourg Compendium of Legislation A –– N° 258', 'Compendium of Legislation A –– N° 258', 'This document is concerned with the law of 18 December 2015 amending, with a view to transposing Directive 2013/34/EU of European Parliament and of the Council of 26 June 2013 on the annual financial statements,consolidated financial statements and related reports of certain types of undertakings, amending Directive 2006/43/EC of the European Parliament and of the Council and repealing Directives 78 / 660/EEC and 83/349/EEC of the Council.', 'This document is concerned with the law of 18 December 2015 amending, with a view to transposing Directive 2013/34/EU of European Parliament and of the Council of 26 June 2013 on the annual financial statements,consolidated financial statements and related reports of certain types of undertakings, amending Directive 2006/43/EC of the European Parliament and of the Council and repealing Directives 78 / 660/EEC and 83/349/EEC of the Council.', 'This document is concerned with the law of 18 December 2015 amending, with a view to transposing Directive 2013/34/EU of European Parliament and of the Council of 26 June 2013 on the annual financial statements,consolidated financial statements and related reports of certain types of undertakings, amending Directive 2006/43/EC of the European Parliament and of the Council and repealing Directives 78 / 660/EEC and 83/349/EEC of the Council.', 'Luxembourg', 'climate', 'in_force', '2015-01-01'::date, 'Luxembourg', 'https://www.carrotsandsticks.org/policies/105_12', ARRAY['mandatory', 'luxembourg', 'other sustainability policy', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('22259fdd-cc4d-5254-b085-c6aaf8d32caa', 'ALFI Code of Conduct for Luxembourg Investment Funds', 'ALFI Code of Conduct for Luxembourg Investment Funds, 2013', 'The ALFI Code of Conduct for Luxembourg Investment Funds, revised in 2013, provides high-level principles and best practice recommendations for governance in the fund industry. It emphasizes sound governance, risk management, and transparency, with a focus on board responsibilities, conflicts of interest, and shareholder rights. The Code aims to ensure compliance with laws and regulations while promoting fair treatment of investors. It encourages annual reviews and adherence to principles in financial statements, enhancing corporate governance standards in the Luxembourg fund industry.', 'The ALFI Code of Conduct for Luxembourg Investment Funds, revised in 2013, provides high-level principles and best practice recommendations for governance in the fund industry. It emphasizes sound governance, risk management, and transparency, with a focus on board responsibilities, conflicts of interest, and shareholder rights. The Code aims to ensure compliance with laws and regulations while promoting fair treatment of investors. It encourages annual reviews and adherence to principles in financial statements, enhancing corporate governance standards in the Luxembourg fund industry.', 'The ALFI Code of Conduct for Luxembourg Investment Funds, revised in 2013, provides high-level principles and best practice recommendations for governance in the fund industry. It emphasizes sound governance, risk management, and transparency, with a focus on board responsibilities, conflicts of interest, and shareholder rights. The Code aims to ensure compliance with laws and regulations while promoting fair treatment of investors. It encourages annual reviews and adherence to principles in financial statements, enhancing corporate governance standards in the Luxembourg fund industry.', 'Luxembourg', 'governance', 'in_force', '2013-01-01'::date, 'Luxembourg', 'https://www.carrotsandsticks.org/policies/105_13', ARRAY['guidance_frameworks', 'other sustainability policy', 'mandatory', 'sdg16', 'sdg9', 'luxembourg']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('47484612-c6f5-5746-ae7a-0f5d14d079cf', 'X Principles of Corporate Governance of the Luxembourg', 'The X Principles of Corporate Governance of the Luxembourg Stock Exchange (3rd Edition 2013)', 'This document revisists the X Principles on the 1st of January 2007, once previously reviewed in October 2009 and incorporates improvements for the purpose of adapting the principles to new realities.', 'This document revisists the X Principles on the 1st of January 2007, once previously reviewed in October 2009 and incorporates improvements for the purpose of adapting the principles to new realities.', 'This document revisists the X Principles on the 1st of January 2007, once previously reviewed in October 2009 and incorporates improvements for the purpose of adapting the principles to new realities.', 'Luxembourg', 'governance', 'in_force', '2013-01-01'::date, 'Luxembourg', 'https://www.carrotsandsticks.org/policies/105_6', ARRAY['guidance_frameworks', 'sdg16', 'disclosure', 'luxembourg', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('51fd6f6c-6db7-5b7d-95e4-a1e7ab9d226e', 'ALFI Code of Conduct for Luxembourg Investment Funds', 'ALFI Code of Conduct for Luxembourg Investment Funds, 2009', 'The purpose of the ALFI Code of Conduct is to provide boards of directors with a framework of high-level principles and best practice recommendations for the governance of Luxembourg investment funds. The Code is “principles” rather than “rules” based in that it relies upon good judgement rather than prescription. As such, the recommendations recognise that the “right approach” for many issues depends on the circumstances. The Code is not designed to supersede applicable law and regulations.', 'The purpose of the ALFI Code of Conduct is to provide boards of directors with a framework of high-level principles and best practice recommendations for the governance of Luxembourg investment funds. The Code is “principles” rather than “rules” based in that it relies upon good judgement rather than prescription. As such, the recommendations recognise that the “right approach” for many issues depends on the circumstances. The Code is not designed to supersede applicable law and regulations.', 'The purpose of the ALFI Code of Conduct is to provide boards of directors with a framework of high-level principles and best practice recommendations for the governance of Luxembourg investment funds. The Code is “principles” rather than “rules” based in that it relies upon good judgement rather than prescription. As such, the recommendations recognise that the “right approach” for many issues depends on the circumstances. The Code is not designed to supersede applicable law and regulations.', 'Luxembourg', 'governance', 'in_force', '2009-01-01'::date, 'Luxembourg', 'https://www.carrotsandsticks.org/policies/105_3', ARRAY['guidance_frameworks', 'mandatory', 'sdg16', 'disclosure', 'sdg9', 'luxembourg']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('b75505a6-a32e-5e6b-b029-09153648c59e', 'Ten Principles of Corporate Governance of the Luxembourg', 'The Ten Principles of Corporate Governance of the Luxembourg Stock Exchange (Revised October 2009)', 'After the entry into force of the Ten Principles on 1 January 2007, and after two years of experience with the application of the Ten Principles in Luxembourg, this document concerns the useful and necessary revision to the Ten Principles in order to improve and adapt them to reality having regard to the initial conclusions drawn from their application.', 'After the entry into force of the Ten Principles on 1 January 2007, and after two years of experience with the application of the Ten Principles in Luxembourg, this document concerns the useful and necessary revision to the Ten Principles in order to improve and adapt them to reality having regard to the initial conclusions drawn from their application.', 'After the entry into force of the Ten Principles on 1 January 2007, and after two years of experience with the application of the Ten Principles in Luxembourg, this document concerns the useful and necessary revision to the Ten Principles in order to improve and adapt them to reality having regard to the initial conclusions drawn from their application.', 'Luxembourg', 'governance', 'in_force', '2009-01-01'::date, 'Luxembourg', 'https://www.carrotsandsticks.org/policies/105_5', ARRAY['guidance_frameworks', 'sdg16', 'disclosure', 'luxembourg', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e9bd28ed-c488-5fde-9ab7-8386a3a56355', 'Ten Principles of Corporate Governance of the Luxembourg', 'The Ten Principles of Corporate Governance of the Luxembourg Stock Exchange, 2006', 'The main objective of the Ten Principles of Corporate Governance is to contribute to the creation of long-term value. A good corporate governance framework should create a balance between a performance-orientated strategy on the one hand, and adherence to reliable risk management systems and internal controls on the other. The latter requires responsibility, integrity and transparency ; a high-performance strategy requires entrepreneurial leadership.', 'The main objective of the Ten Principles of Corporate Governance is to contribute to the creation of long-term value. A good corporate governance framework should create a balance between a performance-orientated strategy on the one hand, and adherence to reliable risk management systems and internal controls on the other. The latter requires responsibility, integrity and transparency ; a high-performance strategy requires entrepreneurial leadership.', 'The main objective of the Ten Principles of Corporate Governance is to contribute to the creation of long-term value. A good corporate governance framework should create a balance between a performance-orientated strategy on the one hand, and adherence to reliable risk management systems and internal controls on the other. The latter requires responsibility, integrity and transparency ; a high-performance strategy requires entrepreneurial leadership.', 'Luxembourg', 'governance', 'in_force', '2006-01-01'::date, 'Luxembourg', 'https://www.carrotsandsticks.org/policies/105_4', ARRAY['guidance_frameworks', 'sdg16', 'disclosure', 'luxembourg', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('5dea1d4a-c5da-58ca-8e1d-241ac06a6256', 'Luxembourg Compendium of Legislation A –– N° 48', 'Compendium of Legislation A –– N° 48', 'The Compendium of Legislation A –– N° 48 from Luxembourg in 2003 focuses on the nomenclature and classification of classified establishments, aiming to assess the environmental impact of public and private projects. It outlines the procedures and criteria for conducting environmental impact assessments, with specific requirements for information disclosure, consultation with authorities, and mitigation measures. The policy applies to construction, installations, and interventions in the natural environment, emphasizing the protection of environmental elements likely to be affected.', 'The Compendium of Legislation A –– N° 48 from Luxembourg in 2003 focuses on the nomenclature and classification of classified establishments, aiming to assess the environmental impact of public and private projects. It outlines the procedures and criteria for conducting environmental impact assessments, with specific requirements for information disclosure, consultation with authorities, and mitigation measures. The policy applies to construction, installations, and interventions in the natural environment, emphasizing the protection of environmental elements likely to be affected.', 'The Compendium of Legislation A –– N° 48 from Luxembourg in 2003 focuses on the nomenclature and classification of classified establishments, aiming to assess the environmental impact of public and private projects. It outlines the procedures and criteria for conducting environmental impact assessments, with specific requirements for information disclosure, consultation with authorities, and mitigation measures. The policy applies to construction, installations, and interventions in the natural environment, emphasizing the protection of environmental elements likely to be affected.', 'Luxembourg', 'governance', 'in_force', '2003-01-01'::date, 'Luxembourg', 'https://www.carrotsandsticks.org/policies/105_9', ARRAY['mandatory', 'luxembourg', 'other sustainability policy', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('62367346-36cf-5a69-8603-a63af1dd2964', 'Luxembourg Compendium of Legislation A –– N° 100', 'Compendium of Legislation A –– N° 100', 'The Compendium of Legislation A – N° 100 from Luxembourg in 2000 focuses on the terms and conditions for research activities receiving assistance from the National Research Fund. The document outlines the roles of the scientific council in assisting the Board of Directors, monitoring activities and programs, and evaluating results for scientific quality and socio-economic relevance. It aims to promote effective coordination of national R&D actions and international cooperation. The policy emphasizes financial contributions for research projects and the dissemination of results.', 'The Compendium of Legislation A – N° 100 from Luxembourg in 2000 focuses on the terms and conditions for research activities receiving assistance from the National Research Fund. The document outlines the roles of the scientific council in assisting the Board of Directors, monitoring activities and programs, and evaluating results for scientific quality and socio-economic relevance. It aims to promote effective coordination of national R&D actions and international cooperation. The policy emphasizes financial contributions for research projects and the dissemination of results.', 'The Compendium of Legislation A – N° 100 from Luxembourg in 2000 focuses on the terms and conditions for research activities receiving assistance from the National Research Fund. The document outlines the roles of the scientific council in assisting the Board of Directors, monitoring activities and programs, and evaluating results for scientific quality and socio-economic relevance. It aims to promote effective coordination of national R&D actions and international cooperation. The policy emphasizes financial contributions for research projects and the dissemination of results.', 'Luxembourg', 'nature', 'in_force', '2000-01-01'::date, 'Luxembourg', 'https://www.carrotsandsticks.org/policies/105_11', ARRAY['sdg4', 'sdg14', 'other sustainability policy', 'regulations', 'sdg17', 'mandatory', 'luxembourg']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('b764d172-70c6-57a9-b079-c1466981d1d1', 'Macedonia ESG Reporting Guidelines', 'ESG Reporting Guidelines', 'The ESG Reporting Guidelines in Macedonia aim to assist listed companies in disclosing their environmental, social, and governance practices in line with international standards. Developed by the Macedonian Stock Exchange and supported by the EBRD, these guidelines target companies seeking to integrate ESG factors into their operations and investor relations.', 'The ESG Reporting Guidelines in Macedonia aim to assist listed companies in disclosing their environmental, social, and governance practices in line with international standards. Developed by the Macedonian Stock Exchange and supported by the EBRD, these guidelines target companies seeking to integrate ESG factors into their operations and investor relations.', 'The ESG Reporting Guidelines in Macedonia aim to assist listed companies in disclosing their environmental, social, and governance practices in line with international standards. Developed by the Macedonian Stock Exchange and supported by the EBRD, these guidelines target companies seeking to integrate ESG factors into their operations and investor relations.', 'Macedonia', 'climate', 'in_force', '2022-01-01'::date, 'Macedonia', 'https://www.carrotsandsticks.org/policies/106_3', ARRAY['sdg16', 'guidance_frameworks', 'macedonia', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('1fc0d52d-09f2-538f-8611-41c95d80e6ec', 'Macedonia ESG Reporting Guidelines', 'ESG Reporting Guidelines, 2019', 'The MSE Corporate Governance Code (“the Code”) advocates that companies report on environmental and social issues based on the principle of transparency and in accordance with relevant legal requirements and good international practices. These Guidelines aim to support this reporting process, while providing a broader view on the reporting context and practices. The Guidelines aim to strengthen companies’ understanding of ESG issues and related reporting frameworks and standards. Moreover, they provide guidance on how companies can communicate their ESG performance in a meaningful way. In short, the key objectives of the Guidelines are to: Provide companies with specific information on meeting the ESG reporting expectations in North Macedonia; Provide a broader context on ESG reporting developments, standards and good practices to prepare for the requirements of the international financial community; Help advance ESG performance in North Macedonia and capture the subsequent benefits.', 'The MSE Corporate Governance Code (“the Code”) advocates that companies report on environmental and social issues based on the principle of transparency and in accordance with relevant legal requirements and good international practices. These Guidelines aim to support this reporting process, while providing a broader view on the reporting context and practices. The Guidelines aim to strengthen companies’ understanding of ESG issues and related reporting frameworks and standards. Moreover, they provide guidance on how companies can communicate their ESG performance in a meaningful way. In short, the key objectives of the Guidelines are to: Provide companies with specific information on meeting the ESG reporting expectations in North Macedonia; Provide a broader context on ESG reporting developments, standards and good practices to prepare for the requirements of the international financial community; Help advance ESG performance in North Macedonia and capture the subsequent benefits.', 'The MSE Corporate Governance Code (“the Code”) advocates that companies report on environmental and social issues based on the principle of transparency and in accordance with relevant legal requirements and good international practices. These Guidelines aim to support this reporting process, while providing a broader view on the reporting context and practices. The Guidelines aim to strengthen companies’ understanding of ESG issues and related reporting frameworks and standards. Moreover, they provide guidance on how companies can communicate their ESG performance in a meaningful way. In short, the key objectives of the Guidelines are to: Provide companies with specific information on meeting the ESG reporting expectations in North Macedonia; Provide a broader context on ESG reporting developments, standards and good practices to prepare for the requirements of the international financial community; Help advance ESG performance in North Macedonia and capture the subsequent benefits.', 'Macedonia', 'climate', 'in_force', '2019-01-01'::date, 'Macedonia', 'https://www.carrotsandsticks.org/policies/106_2', ARRAY['guidance_frameworks', 'sdg7', 'sdg11', 'sdg16', 'disclosure', 'sdg9', 'macedonia', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('63b048ba-fb69-5768-b1ea-a10280bfa624', 'Macedonia Corporate Governance Code for Companies Listed on the', 'Corporate Governance Code for Companies Listed on the Macedonian Stock Exchange', 'This document is concerned with the Corporate Governance code for companies listed on the Macedonian Stock Exchange and is based on the OECD Corporate Governance Principles.', 'This document is concerned with the Corporate Governance code for companies listed on the Macedonian Stock Exchange and is based on the OECD Corporate Governance Principles.', 'This document is concerned with the Corporate Governance code for companies listed on the Macedonian Stock Exchange and is based on the OECD Corporate Governance Principles.', 'Macedonia', 'governance', 'in_force', '2006-01-01'::date, 'Macedonia', 'https://www.carrotsandsticks.org/policies/106_1', ARRAY['guidance_frameworks', 'other sustainability policy', 'mandatory', 'sdg16', 'macedonia']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('1157fbc7-ee33-5ab6-8ada-0d0dfd02e12c', 'Malawi Code II. Code of Best Practice', 'The Malawi Code II. Code of Best Practice for Corporate Governance in Malawi Overarching Provisions', 'This is an updated version of the Malawi Code of Best Practice. This Revised Code was commissioned by the IOD following recommendations emanating from the World Bank Corporate Governance ROSC (Report on the Observance of Standards and Codes) which was completed in 2007. It aims at incorporating lessons learnt from the operation of the existing Code introduced in 2001 and international best practice.', 'This is an updated version of the Malawi Code of Best Practice. This Revised Code was commissioned by the IOD following recommendations emanating from the World Bank Corporate Governance ROSC (Report on the Observance of Standards and Codes) which was completed in 2007. It aims at incorporating lessons learnt from the operation of the existing Code introduced in 2001 and international best practice.', 'This is an updated version of the Malawi Code of Best Practice. This Revised Code was commissioned by the IOD following recommendations emanating from the World Bank Corporate Governance ROSC (Report on the Observance of Standards and Codes) which was completed in 2007. It aims at incorporating lessons learnt from the operation of the existing Code introduced in 2001 and international best practice.', 'Malawi', 'climate', 'in_force', '2010-01-01'::date, 'Malawi', 'https://www.carrotsandsticks.org/policies/108_1', ARRAY['regulations', 'malawi', 'mandatory', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('55becdf2-b1a3-5c80-8622-15f28617228c', 'Malaysia Sustainability Reporting Guide', 'Sustainability Reporting Guide 3rd Edition, 2022', 'This Sustainability Reporting Guide (“Guide”) details the business case for embedding sustainability and provides guidance on how this can be achieved. It also provides specific guidance on the information that should be disclosed when producing a Sustainability Statement in the Annual Report in accordance with Bursa Malaysia’s Listing Requirements (“LR”).', 'This Sustainability Reporting Guide (“Guide”) details the business case for embedding sustainability and provides guidance on how this can be achieved. It also provides specific guidance on the information that should be disclosed when producing a Sustainability Statement in the Annual Report in accordance with Bursa Malaysia’s Listing Requirements (“LR”).', 'This Sustainability Reporting Guide (“Guide”) details the business case for embedding sustainability and provides guidance on how this can be achieved. It also provides specific guidance on the information that should be disclosed when producing a Sustainability Statement in the Annual Report in accordance with Bursa Malaysia’s Listing Requirements (“LR”).', 'Malaysia', 'climate', 'in_force', '2022-01-01'::date, 'Malaysia', 'https://www.maicsa.org.my/media/8632/technical_announcements_230925_1_2.pdf', ARRAY['sdg13', 'malaysia', 'mandatory', 'sdg16', 'mandatory_regulations', 'sdg12', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('59d3a8b0-f414-54b6-9837-9cc3cbf98c74', 'Malaysian Corporate Governance (As at 28 April', 'Malaysian Corporate Governance (As at 28 April 2021)', 'This is an updated version of the Malaysian Code on Corporate Governance to ensure that it remains relevant and is aligned with globally recognised best practices and standards.', 'This is an updated version of the Malaysian Code on Corporate Governance to ensure that it remains relevant and is aligned with globally recognised best practices and standards.', 'This is an updated version of the Malaysian Code on Corporate Governance to ensure that it remains relevant and is aligned with globally recognised best practices and standards.', 'Malaysia', 'governance', 'in_force', '2021-01-01'::date, 'Malaysia', 'https://www.carrotsandsticks.org/policies/109_31', ARRAY['malaysia', 'regulations', 'mandatory', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('9c82160d-f961-5e48-bf88-08de8213d3eb', 'Malaysia Climate Change and Principle-based Taxonomy', 'Climate Change and Principle-based Taxonomy', 'This document aims to: (a) provide an overview of climate change and its impact on businesses and households as well as the broader economy;
(b) introduce a principle-based taxonomy for FIs to assess and categorise economic activities according to the extent to which the activities meet climate objectives and promote the transition to a low-carbon economy. The taxonomy also incorporates the consideration of broader environmental outcomes through the principle of no significant harm, with specific regard to how business operations affect pollution, biodiversity and resource efficiency. In supporting an orderly transition, the taxonomy recognises remediation measures and introduces a progressive system of transition categories to acknowledge concrete efforts and commitments by businesses to adopt sustainable practices; and (c) facilitate standardised classification and reporting of climate-related exposures to support risk assessments at the institution and systemic levels, strengthen accountability and market transparency, and encourage financial flows towards supporting climate objectives. FIs can also leverage on the taxonomy in the design and structuring of green finance solutions and services to accelerate development of green sectors and activities, and decarbonisation efforts.', 'This document aims to: (a) provide an overview of climate change and its impact on businesses and households as well as the broader economy;
(b) introduce a principle-based taxonomy for FIs to assess and categorise economic activities according to the extent to which the activities meet climate objectives and promote the transition to a low-carbon economy. The taxonomy also incorporates the consideration of broader environmental outcomes through the principle of no significant harm, with specific regard to how business operations affect pollution, biodiversity and resource efficiency. In supporting an orderly transition, the taxonomy recognises remediation measures and introduces a progressive system of transition categories to acknowledge concrete efforts and commitments by businesses to adopt sustainable practices; and (c) facilitate standardised classification and reporting of climate-related exposures to support risk assessments at the institution and systemic levels, strengthen accountability and market transparency, and encourage financial flows towards supporting climate objectives. FIs can also leverage on the taxonomy in the design and structuring of green finance solutions and services to accelerate development of green sectors and activities, and decarbonisation efforts.', 'This document aims to: (a) provide an overview of climate change and its impact on businesses and households as well as the broader economy;
(b) introduce a principle-based taxonomy for FIs to assess and categorise economic activities according to the extent to which the activities meet climate objectives and promote the transition to a low-carbon economy. The taxonomy also incorporates the consideration of broader environmental outcomes through the principle of no significant harm, with specific regard to how business operations affect pollution, biodiversity and resource efficiency. In supporting an orderly transition, the taxonomy recognises remediation measures and introduces a progressive system of transition categories to acknowledge concrete efforts and commitments by businesses to adopt sustainable practices; and (c) facilitate standardised classification and reporting of climate-related exposures to support risk assessments at the institution and systemic levels, strengthen accountability and market transparency, and encourage financial flows towards supporting climate objectives. FIs can also leverage on the taxonomy in the design and structuring of green finance solutions and services to accelerate development of green sectors and activities, and decarbonisation efforts.', 'Malaysia', 'climate', 'in_force', '2021-01-01'::date, 'Malaysia', 'https://www.carrotsandsticks.org/policies/109_32', ARRAY['sdg13', 'other sustainability policy', 'malaysia', 'voluntary', 'sdg16', 'sdg12', 'sdg15', 'voluntary_frameworks']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ef962324-dcee-53a2-b959-f9dd2fedc6c6', 'Malaysia Climate Change and Principle-based Taxonomy', 'Climate Change and Principle-based Taxonomy 2021', 'This document provides a climate change overview, introduces a taxonomy for financial institutions (FIs) to classify eco-friendly activities, and facilitates standard reporting to support risk assessment and promote an orderly transition to a low-carbon economy, encouraging green finance development.', 'This document provides a climate change overview, introduces a taxonomy for financial institutions (FIs) to classify eco-friendly activities, and facilitates standard reporting to support risk assessment and promote an orderly transition to a low-carbon economy, encouraging green finance development.', 'This document provides a climate change overview, introduces a taxonomy for financial institutions (FIs) to classify eco-friendly activities, and facilitates standard reporting to support risk assessment and promote an orderly transition to a low-carbon economy, encouraging green finance development.', 'Malaysia', 'climate', 'in_force', '2021-01-01'::date, 'Malaysia', 'https://www.carrotsandsticks.org/policies/109_42', ARRAY['sdg13', 'voluntary_frameworks', 'malaysia', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('348cec9f-d944-5148-9550-4c9dd6fbfb4a', 'Sustainable and Responsible Investment Roadmap for The Malaysian', 'Sustainable and Responsible Investment Roadmap for The Malaysian Capital Market', 'The 20 recommendations contained in this SRI Roadmap are mapped to five overarching strategies aimed at driving the development of a vibrant SRI ecosystem for Malaysia as well as the region. These strategies serve to expand the range of SRI instruments, issuers, investors and ancillary services, while strengthening disclosure and governance by drawing synergies from our existing global leadership in the closely-aligned field of Islamic finance.', 'The 20 recommendations contained in this SRI Roadmap are mapped to five overarching strategies aimed at driving the development of a vibrant SRI ecosystem for Malaysia as well as the region. These strategies serve to expand the range of SRI instruments, issuers, investors and ancillary services, while strengthening disclosure and governance by drawing synergies from our existing global leadership in the closely-aligned field of Islamic finance.', 'The 20 recommendations contained in this SRI Roadmap are mapped to five overarching strategies aimed at driving the development of a vibrant SRI ecosystem for Malaysia as well as the region. These strategies serve to expand the range of SRI instruments, issuers, investors and ancillary services, while strengthening disclosure and governance by drawing synergies from our existing global leadership in the closely-aligned field of Islamic finance.', 'Malaysia', 'nature', 'in_force', '2019-01-01'::date, 'Malaysia', 'https://www.carrotsandsticks.org/policies/109_14', ARRAY['other sustainability policy', 'malaysia', 'mandatory', 'sdg16', 'mandatory_regulations', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('7e76de2f-4a1b-5a2e-a3d7-fa077c583b75', 'Malaysia Sustainable Reporting Guide', 'Sustainable Reporting Guide, 2018', 'This Sustainability Reporting Guide seeks to provide guidance on how to embed sustainability in your organisation and help you identify, evaluate and manage your material EES risks and opportunities. It also highlights the business case for sustainability, providing case studies to illustrate how sustainability may add value to your organisation, and also example disclosures to aid you in your preparation of the Sustainability Statement in accordance with the Listing Requirements of Bursa Malaysia Securities Berhad (“Bursa Malaysia”).', 'This Sustainability Reporting Guide seeks to provide guidance on how to embed sustainability in your organisation and help you identify, evaluate and manage your material EES risks and opportunities. It also highlights the business case for sustainability, providing case studies to illustrate how sustainability may add value to your organisation, and also example disclosures to aid you in your preparation of the Sustainability Statement in accordance with the Listing Requirements of Bursa Malaysia Securities Berhad (“Bursa Malaysia”).', 'This Sustainability Reporting Guide seeks to provide guidance on how to embed sustainability in your organisation and help you identify, evaluate and manage your material EES risks and opportunities. It also highlights the business case for sustainability, providing case studies to illustrate how sustainability may add value to your organisation, and also example disclosures to aid you in your preparation of the Sustainability Statement in accordance with the Listing Requirements of Bursa Malaysia Securities Berhad (“Bursa Malaysia”).', 'Malaysia', 'climate', 'in_force', '2018-01-01'::date, 'Malaysia', 'https://www.carrotsandsticks.org/policies/109_10', ARRAY['sdg13', 'malaysia', 'mandatory', 'sdg16', 'mandatory_regulations', 'sdg12', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('09942404-a6af-59af-9257-0f7d4608ec93', 'Malaysian Code of Corporate Governance', 'Malaysian Code of Corporate Governance, 2017', 'This Malaysian Code on Corporate Governance reflects global principles and internationally recognised practices of corporate governance which are above and beyond the minimum required by statute, regulations or those prescribed by Bursa Malaysia.', 'This Malaysian Code on Corporate Governance reflects global principles and internationally recognised practices of corporate governance which are above and beyond the minimum required by statute, regulations or those prescribed by Bursa Malaysia.', 'This Malaysian Code on Corporate Governance reflects global principles and internationally recognised practices of corporate governance which are above and beyond the minimum required by statute, regulations or those prescribed by Bursa Malaysia.', 'Malaysia', 'governance', 'in_force', '2017-01-01'::date, 'Malaysia', 'https://www.carrotsandsticks.org/policies/109_11', ARRAY['malaysia', 'regulations', 'mandatory', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
